// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // fuzz parameters: an address payer (we'll use vm.addr to get a funded EOA),
    // a uint256 v value, and a uint256 tosCount to build a non-empty array length
    function testFuzz_property(uint256 key, uint256 v, uint256 tosCount) public {
        // keep tosCount within a small but wide range and ensure non-empty
        uint256 len = bound(tosCount, 1, 5);

        // create an adversarial callee that always succeeds and records calls
        Recorder rec = new Recorder();

        // prepare tos array of addresses that all point to our recorder
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) tos[i] = address(rec);

        // fund an EOA (derived from key) to be the `from` parameter if needed
        address from = vm.addr(uint256(keccak256(abi.encodePacked(key))));
        vm.deal(from, 1 ether);

        // call transfer and observe whether it returns (ok=true) or reverts (ok=false)
        bool ok;
        try c.transfer(from, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: reference C always returns (ok == true) for any non-empty _tos
        // The mutant that reverts at the end will make ok == false for some inputs.
        assertTrue(ok);
    }
}

// Recorder that implements the exact called function signature so C's low-level call
// resolves to this function. It records a counter of how many times it was invoked and
// the last parameters seen. It always returns true (no revert) to exercise the normal path.
contract Recorder {
    uint public calls;
    address public lastFrom;
    address public lastTo;
    uint public lastV;

    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls += 1;
        lastFrom = from;
        lastTo = to;
        lastV = v;
        return true;
    }
}
